<script setup lang="ts">
import {computed,onMounted,ref} from 'vue'
import '../styles/student-workspace.css'
import {homeworkDateLabel} from '../student-homework-filters'
import {scheduleApi} from '../schedules'
import profileAvatar from '../assets/student-avatar.svg'
import StudentIcon from './StudentIcon.vue'
type Destination='notices'|'homework'|'school'|'profile'|'semester'|'course'|'schedule'|'jobs'|'home'|'life'|'settings'|'eat'
const props=defineProps<{items:{page:Destination;title:string;icon:string}[]}>()
const emit=defineEmits<{open:[page:Destination];context:[school:{name:string;level:string}|null]}>()
const school=ref<{name:string;level:string}|null>(null),loading=ref(false),error=ref('')
const homework=ref<any[]>([]),today=ref(''),previewError=ref(false)
const nextTask=computed(()=>homework.value.filter(h=>!['submitted','reviewed','late'].includes(h.progress_status)).sort((a,b)=>a.due_on.localeCompare(b.due_on)||a.id-b.id)[0])
const hints:Partial<Record<Destination,string>>={notices:'School and class updates',homework:'Assignments from your teachers',school:'Class, timetable & subjects',schedule:'Your weekly routine',course:'Subjects & teachers',eat:'Menu, hours & location',profile:'Your personal information',jobs:'Search and saved jobs',semester:'Assigned semesters'}
const order:Destination[]=['school','schedule','notices','homework','course','eat','jobs','semester']
function openNextTask(){const h=nextTask.value;if(!h)return;const url=new URL(window.location.href);url.searchParams.delete('homeworkDue');if(h.due_on<today.value){url.searchParams.set('homeworkHistory','open');url.searchParams.set('historySubject',h.course_name)}else{url.searchParams.set('homeworkSubject',h.course_name);url.searchParams.delete('homeworkHistory')}window.history.replaceState(window.history.state,'',url);emit('open','homework')}
function features(){return order.flatMap(page=>props.items.filter(item=>item.page===page))}
async function load(){loading.value=true;error.value='';previewError.value=false;const [schoolResult,homeworkResult]=await Promise.allSettled([scheduleApi('student/school'),scheduleApi('student/homework')]);if(schoolResult.status==='fulfilled'){school.value=schoolResult.value.school;emit('context',schoolResult.value.school)}else error.value=schoolResult.reason instanceof Error?schoolResult.reason.message:'Unable to load school information.';if(homeworkResult.status==='fulfilled'){homework.value=homeworkResult.value.homework;today.value=homeworkResult.value.today}else previewError.value=true;loading.value=false}
onMounted(load)
</script>
<template>
<section class="student-home" aria-label="Student home">
 <div class="welcome"><div class="school-heading"><h2>{{school?.name||'Your student workspace'}}</h2><button v-if="items.some(item=>item.page==='profile')" type="button" class="profile-shortcut" aria-label="Open student profile" title="Student profile" @click="emit('open','profile')"><img :src="profileAvatar" alt="" width="48" height="48"></button></div><span>Choose what you need. Everything is one tap away.</span></div>
 <p v-if="loading" class="home-status" role="status">Loading your school…</p>
 <p v-if="error" class="error" role="alert">{{error}} <button type="button" class="retry" @click="load">Retry</button></p>
 <button v-if="nextTask" type="button" class="home-next-task" @click="openNextTask"><span><small>{{nextTask.due_on<today?'Homework to follow up':'Next homework'}}</small><strong>{{nextTask.title}}</strong></span><span class="next-task-date">{{nextTask.course_name}}<small>{{nextTask.due_on<today?'Past due: '+nextTask.due_on:homeworkDateLabel(nextTask.due_on,today)}}</small></span></button><p v-if="previewError" class="home-status">Homework preview unavailable. <button type="button" class="retry" @click="load">Retry</button></p><nav class="feature-tabs" aria-label="Student features"><button v-for="item in features()" :key="item.page" type="button" class="feature-tab" @click="emit('open',item.page)"><span class="feature-icon"><StudentIcon :name="item.icon"/></span><span class="feature-copy"><strong>{{item.title}}</strong><small>{{hints[item.page]}}</small></span></button></nav>
</section>
</template>
<style scoped>
/* Hallmark · shape: app screen · genre: modern-minimal · theme: brand · redesign: full · signature: next homework shortcut · states: loading empty error full · v2.0.0 */
/* Hallmark · pre-emit critique: familiar shell retained; school heading now owns the profile shortcut. */
.student-home{min-width:0}.welcome{padding:4px 0 24px}.welcome h2{font-size:24px!important;line-height:1.35;margin:0 0 8px!important;color:var(--student-ink);overflow-wrap:anywhere}.welcome>span{font-size:13px;color:var(--student-muted);line-height:1.6}.feature-tabs{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.feature-tab{display:flex;align-items:center;gap:16px;min-height:100px;border:1px solid var(--student-rule);border-radius:12px;background:var(--student-soft);padding:16px;text-align:left;color:var(--student-ink);width:100%;margin:0}.feature-tab:hover{background:var(--student-hover);border-color:var(--student-border-hover)}.feature-tab:focus-visible{outline:3px solid var(--student-focus);outline-offset:3px}.feature-icon{display:grid;place-items:center;background:var(--student-icon);border-radius:10px;width:44px;height:44px;flex-shrink:0}.feature-icon svg{width:24px;height:24px}.feature-copy{min-width:0;flex:1}.feature-copy strong,.feature-copy small{display:block}.feature-copy strong{font-size:15px;margin-bottom:8px}.feature-copy small{font-size:11px;line-height:1.5;color:var(--student-muted);font-weight:400}.feature-arrow{color:var(--student-arrow);font-size:24px}.home-status{font-size:12px;color:var(--student-muted)}.retry{font-size:12px;padding:8px 12px}@media(max-width:500px){.welcome{padding-bottom:16px}.welcome h2{font-size:20px!important}.feature-tabs{gap:12px}.feature-tab{min-height:124px;flex-direction:column;align-items:flex-start;gap:12px;padding:16px;position:relative}.feature-icon{height:34px;width:34px;border-radius:8px}.feature-icon svg{width:20px;height:20px}.feature-copy strong{font-size:14px;margin-bottom:4px}.feature-copy small{font-size:10px}.feature-arrow{position:absolute;right:12px;top:16px;font-size:20px}}
.school-heading{display:flex;align-items:center;justify-content:space-between;gap:16px;margin-bottom:8px}.school-heading h2{flex:1;min-width:0;margin:0!important}.student-home .profile-shortcut{display:flex;align-items:center;gap:8px;flex-shrink:0;width:auto;min-height:48px;margin:0;padding:0;background:transparent;color:var(--student-accent);border:0;border-radius:28px;font-size:12px}.profile-shortcut img{display:block;width:48px;height:48px;border:1px solid var(--student-rule);border-radius:50%;background:var(--student-avatar);box-sizing:border-box}.profile-shortcut:hover img{border-color:var(--student-accent)}.profile-shortcut:focus-visible{outline:3px solid var(--student-focus);outline-offset:4px}@media(max-width:500px){.school-heading{gap:12px}.profile-shortcut span{display:none}.profile-shortcut img{width:44px;height:44px}}
.student-home .home-next-task{display:flex;justify-content:space-between;align-items:center;gap:16px;width:100%;margin:0 0 16px;padding:12px 0;border:0;border-top:1px solid var(--student-rule);border-bottom:1px solid var(--student-rule);border-radius:0;background:transparent;color:var(--student-ink);text-align:left;min-height:64px}.home-next-task>span{min-width:0}.home-next-task strong{display:block;font-size:15px;overflow-wrap:anywhere}.home-next-task small{display:block;font-size:12px;color:var(--student-muted);margin:0 0 4px;font-weight:400}.home-next-task .next-task-date{text-align:right;font-size:12px;flex-shrink:0}.next-task-date small{margin:4px 0 0}.home-next-task:hover{background:var(--student-soft)}.home-next-task:focus-visible,.retry:focus-visible{outline:2px solid var(--student-focus);outline-offset:3px}.school-heading h2{overflow-wrap:break-word;min-width:0}.student-home .retry{min-height:44px}@media(prefers-reduced-motion:reduce){.student-home *{scroll-behavior:auto}}
.feature-tab:active,.home-next-task:active{background:var(--student-hover)}.welcome h2{text-wrap:balance}</style>
